"""Share of the total minutes per visit."""
from visits import load_visits


def minutes_shares(visits):
    """Return each visit's share of the total minutes, in order."""
    total = sum(x.minutes for x in visits)
    return [x.minutes / total for x in visits]


def stored_shares():
    """Shares for the stored visits."""
    return minutes_shares(load_visits())


def top_share(visits):
    """Return the largest share, or 0.0 when there are no visits."""
    shares = minutes_shares(visits)
    return max(shares) if shares else 0.0

