from visits import load_visits, ROWS
from breakdown import minutes_shares, stored_shares, top_share

TOTAL = sum(v for _, v in ROWS)


def test_stored_shares():
    shares = stored_shares()
    assert len(shares) == len(ROWS) and abs(sum(shares) - 1.0) < 1e-9


def test_generator_values():
    shares = minutes_shares(load_visits())
    assert abs(shares[0] - ROWS[0][1] / TOTAL) < 1e-9 and abs(shares[-1] - ROWS[-1][1] / TOTAL) < 1e-9


def test_list_input():
    shares = minutes_shares(list(load_visits()))
    assert abs(shares[1] - ROWS[1][1] / TOTAL) < 1e-9


def test_top_share_generator():
    assert abs(top_share(load_visits()) - max(v for _, v in ROWS) / TOTAL) < 1e-9


def test_empty():
    assert minutes_shares(iter([])) == [] and top_share(iter([])) == 0.0
